  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());
  const [isDownloading, setIsDownloading] = useState(false);

  const fetchMySlip = async () => {
    try {
      setLoading(true);
      setSlipData(null); 
      
      const token = await AsyncStorage.getItem('userToken');
      const permsStr = await AsyncStorage.getItem('userPermissions');
      const perms = permsStr ? JSON.parse(permsStr).map((p: string) => p.toUpperCase()) : [];
      setPermissions(perms);

      if (perms.includes('SALARY-SLIP:VIEW') || perms.includes('PAYROLL:VIEW')) {
          const config = { headers: { Authorization: `Bearer ${token}` } };
          let foundSlip = null;

          const exactUrl = `${API_BASE}/payroll/my-slip?month=${selectedMonth}&year=${selectedYear}&_t=${Date.now()}`;
          
          try {
              const res = await axios.get(exactUrl, config);
              const rawData = res.data;
              if (rawData?.data) {
                  if (Array.isArray(rawData.data) && rawData.data.length > 0) foundSlip = rawData.data[0];
                  else if (!Array.isArray(rawData.data) && rawData.data._id) foundSlip = rawData.data;
              } else if (rawData?._id) foundSlip = rawData;
          } catch (e: any) {
              console.log("Payslip fetch failed:", e.message);
          }

          setSlipData(foundSlip || null); 
      }
    } catch (err: any) {
      setSlipData(null);
    } finally {
      setLoading(false);
    }
  };

